UNITS = [
 dict(id='A2-01',title='Escolher um espaço que serve ao grupo',prerequisites=['A1-03','A1-04','A1-08'],reading_questions=5,
 goal='Comparar três espaços com limites de horário, preço e capacidade; justificar uma escolha e recusar uma opção inadequada.',
 targets=['Comparativos','Superlativos e igualdade','Too e enough','Few/little e some quantidade','Tempo e duração'],
 support='available = disponível para uso, sem significar reservado; enough = suficiente; quiet = silencioso; reliable = confiável, sem garantia absoluta; fit = caber; workshop = oficina/encontro de prática; fee = taxa; total = total; per hour = por hora; seats = assentos; stairs = escadas; lift = elevador; at street level = no nível da rua; booking = reserva; until = até; cheaper = mais barato; cheapest = o mais barato; bigger = maior; as quiet as = tão silencioso quanto; a few = alguns; few = poucos, com ênfase na escassez; a little = um pouco; little = pouco, com ênfase na escassez. Todos os preços e avaliações são fictícios.',
 explanation='Compare duas opções com -er/more + than: A is cheaper than B; B is more expensive than A. Para escolher extremo dentro de um conjunto: A is the cheapest of the three. Não usar more cheaper. As…as compara igualdade: B is as quiet as C. Too expensive indica que excede um limite; very expensive apenas intensifica. Enough vem antes do nome (enough seats) e depois do adjetivo (big enough). A few seats/a little time indicam alguma disponibilidade; few seats/little time destacam escassez, sem determinar sozinhos se basta. For two hours é duração; from two to four delimita intervalo; in two hours pode indicar daqui a duas horas.',
 readings=[('E-mail de organização','Hello, everyone. We need a room for six adults on Saturday, from two to four in the afternoon. Our total budget is thirty credits. We need six seats and a quiet space because we are going to record short conversations. One participant cannot use stairs, so a room upstairs without a lift will not work for this group. We have a little time to compare the offers before we reply. Please do not choose only by price. A room may be cheap but too small, or available at the wrong time. We have not made a booking. We need to confirm the room and the total fee first.'),('Três ofertas, válidas para este exercício','Room A: 18 credits total for two hours. Four seats. At street level. Quiet. Available Saturday, 2–4 p.m.\nRoom B: 28 credits total for two hours. Eight seats. At street level. Quiet. Available Saturday, 2–4 p.m.\nRoom C: 24 credits total for two hours. Eight seats. Upstairs, no lift. As quiet as Room B. Available Saturday, 2–4 p.m.\nThe fee is for the whole room, not for each person. A message saying that a room is available is not a booking confirmation. The organiser must accept an offer and receive confirmation from the centre.')],
 audio='Organiser: Is Room B still available from two to four on Saturday?\nReceptionist: Yes. There are eight seats.\nOrganiser: Is twenty-eight credits the total fee?\nReceptionist: Yes, for the whole room for two hours.\nOrganiser: And it’s at street level?\nReceptionist: Yes.\nOrganiser: We’d like Room B, please.\nReceptionist: I’ll send the confirmation. Please check it when it arrives.',
 questions=[('Quais três restrições, além de preço, podem eliminar uma opção?','Seis lugares; horário 14h–16h; acesso sem escadas. Espaço silencioso também é exigido; aceitar este quarto critério.'),('Qual opção é a mais barata e por que não atende ao grupo?','A; tem só quatro lugares para seis pessoas.'),('Por que C não serve apesar de oito lugares e preço dentro do limite?','Escadas sem elevador impedem o acesso previsto no cenário.'),('B é mais silenciosa que C segundo a oferta?','Não; C é as quiet as B. A fonte afirma igualdade.'),('A taxa de B é por pessoa ou pelo espaço inteiro?','28 pelo espaço inteiro, por duas horas.'),('Na escuta, os oito lugares foram confirmados?','Sim.'),('Qual intervalo a pessoa confirma?','Sábado, 14h–16h.'),('A gravação prova que a confirmação escrita já chegou?','Não; a recepção promete enviá-la. Recebimento ainda pendente.')],
 practice=[('Compare preços A18 e B28 com cheaper.','A is cheaper than B.'),('Escolha o menor preço entre as três com cheapest.','A is the cheapest of the three.'),('Corrija: B is more bigger than A.','B is bigger than A; o tamanho aqui pode ser expresso como capacidade se explicitado. Não inferir área em m².'),('Complete: A doesn’t have ___ seats for six adults.','enough.'),('Complete: A isn’t big ___.','enough, no sentido de capacidade do cenário.'),('Explique diferença entre too expensive e very expensive.','Too excede um limite; very intensifica sem afirmar necessariamente que ultrapassa o limite.'),('Escolha: a few / a little time.','a little time.'),('Escolha: a few / a little seats.','a few seats.'),('Duração: for/in two hours, quando o evento dura duas horas.','for two hours.'),('Transforme 2–4 p.m. em intervalo com from/to.','From two to four in the afternoon.')],
 guided='A recebe necessidades do e-mail; B recebe as ofertas. A pergunta preço total, lugares, horário e acesso. B responde a cada campo antes de recomendar. A escolhe B, compara com A e C e pede confirmação. B diz que vai enviar; A registra “requested, confirmation pending” (solicitada, confirmação pendente). Troquem os papéis.',
 model='A: We need enough seats for six people. Is B more expensive than C?\nB: Yes, but C is upstairs without a lift.\nA: A is cheaper, but it’s too small. We’d like B from two to four.\nB: I’ll send the confirmation.\nA: Thank you. We’ll check it.',
 transfer='Novo grupo: sete adultos, domingo 10h–12h, orçamento 35, todos precisam de acesso no nível da rua. D: 30 total, seis lugares, nível da rua; E: 34 total, oito lugares, nível da rua; F: 26 total, oito lugares, escadas sem elevador. Todos silenciosos e disponíveis no horário. Escreva recomendação de quatro frases: opção escolhida, duas rejeições justificadas e o que ainda precisa de confirmação. Explique em português ao grupo por que “mais barato” não determina a decisão.',
 evidence='Escolher E: oito lugares, acesso e preço 34 dentro de 35. D não tem lugares suficientes; F falha no acesso. Solicitar confirmação; não declarar recebido o que ainda não veio. Para preço, F is the cheapest; E is more expensive than F. Não chamar E de maior em área, que não foi informada.',
 review='No encontro seguinte: três salas silenciosas no nível da rua, horário adequado. Necessidade: cinco pessoas, orçamento 22. A custa20 e tem4 lugares; B custa22 e tem6; C custa24 e tem8. Escolha e dê dois contrastes usando enough e too.',
 review_answer='B atende. A doesn’t have enough seats; C is too expensive para orçamento 22. B custa exatamente o limite, não acima dele.',
 phon='Compare os campos PRICE / SEATS / TIME em fala clara. O destinatário repete números e identifica se são preço, capacidade ou duração; um número ouvido corretamente no campo errado não resolve a tarefa.',
 teacher='A escolha depende das condições dadas, não de recomendações reais de acessibilidade de um imóvel. Distinguir grande em área de suficiente em capacidade. Volte a A1-03 se a descrição de lugar bloquear a comparação. O perfect em We have not made a booking é apoio receptivo: significa ainda não fizemos reserva; não exigir produção antes de A2-04.'),
 dict(id='A2-02',title='Lidar com atraso e combinar a chegada',prerequisites=['A2-01','A1-02','A1-08'],reading_questions=5,
 goal='Recalcular uma chegada após atraso, distinguir horário público de encontro pessoal e combinar uma alternativa condicional.',
 targets=['Decisão e previsão com will','Arranjos e horários','Condições gerais e futuras','Perguntas indiretas iniciais'],
 support='delay = atraso; delayed by = atrasado em uma duração; platform = plataforma de embarque; miss the train = perder o trem por não embarcar; get back = voltar; pick someone up = buscar alguém; return ticket = ida e volta; departure = partida; arrival = chegada; timetable = tabela de horários; instead = em vez disso; entrance = entrada; station = estação; signal = sinal; exactly = exatamente. Horários em formato 24h na tabela; two forty = 14h40 neste contexto. Where the platform is = onde fica a plataforma.',
 explanation='Horários públicos usam presente simples: The train leaves at 14:20. Arranjo pessoal pode usar presente contínuo com referência futura: I’m meeting Jo at 15:00. Will + base anuncia decisão após notícia: It’s late. I’ll call Jo. Going to pode apresentar plano anterior. If + presente, will na consequência no padrão inicial: If we arrive late, we’ll meet at the café. Não usar if we will arrive para essa condição. Pergunta indireta conserva ordem afirmativa interna: Could you tell me where platform six is?; comparar Where is platform six? direta. Não fazer inversão duas vezes.',
 readings=[('Mensagem antes da viagem','Hi Jo. I have a return ticket for Saturday. My train leaves at 14:20 and arrives at 15:00. I’m meeting you outside the main station entrance at 15:10. I’m going to visit the museum first, but I can change that plan if the train is late. Please don’t wait on the platform: I don’t know which platform we will use when we arrive. I’m getting back on the 18:00 train. If I miss that train, I’ll call you before I choose another one. I’ll keep the ticket information on paper because my phone sometimes has no signal.'),('Atualização oficial fictícia','Train 24, Saturday. Scheduled departure: 14:20. Scheduled arrival: 15:00. Delay: 20 minutes. Updated departure: 14:40. Updated arrival: 15:20. Departure platform changed from 2 to 6.\nThis notice changes the outward journey only. The return train still leaves at 18:00. Platform 6 is the departure platform at the starting station; the notice does not identify the arrival platform. The twenty-minute delay is a duration, not an arrival time. Travellers should use the updated times for this exercise.')],
 audio='Traveller: Could you tell me where platform six is?\nStaff: Next to platform five. Your train leaves at two forty.\nTraveller: Thank you. I’ll call Jo now.\nJo: Hello?\nTraveller: The train arrives at three twenty. Can we meet at three thirty?\nJo: Yes. Outside the main entrance. If it rains, we’ll meet at the station café.\nTraveller: Three thirty. If it rains, the café. Thank you.',
 questions=[('Qual era o encontro combinado inicialmente?','15h10, fora da entrada principal.'),('Qual é a nova chegada e como ela se relaciona ao atraso?','15h20, vinte minutos depois de 15h.'),('A plataforma6 é da partida ou da chegada?','Partida; chegada não informada.'),('O trem de volta também atrasou segundo a fonte?','Não; continua18h, sem atraso informado.'),('A mensagem permite afirmar que a visita ao museu ocorrerá com certeza?','Não; é plano ajustável em caso de atraso.'),('Qual novo horário Jo aceita na escuta?','15h30.'),('Onde se encontram se chover?','Café da estação.'),('A fala afirma que já está chovendo?','Não; apresenta condição, não ocorrência observada.')],
 practice=[('Complete horário oficial: The train ___ at 14:40. (leave)','leaves.'),('Complete arranjo: I ___ meeting Jo at 15:30.','am.'),('Você decide telefonar após ler notícia. Complete: I___ call Jo now.','I’ll.'),('Corrija: If it will rain, we’ll meet inside.','If it rains, we’ll meet inside.'),('Dê condição de chegada tardia: If we arrive late, … com call.','If we arrive late, we’ll call Jo.'),('Transforme Where is platform six? em pedido com Could you tell me.','Could you tell me where platform six is?'),('Corrija: Do you know where is the entrance?','Do you know where the entrance is?'),('Diferencie delay by 20 minutes e arrival 15:20.','O primeiro é duração do atraso; o segundo é horário de chegada.')],
 guided='A tem atualização Train24; B é Jo com encontro antigo 15h10. A comunica mudança, propõe15h30 e confirma plano se chover. B registra hora e dois lugares com condição. Depois B pergunta sobre a volta; A só confirma 18h, sem inventar plataforma de chegada.',
 model='A: The train arrives at three twenty. I’ll call you when I arrive. Can we meet at three thirty?\nB: Yes. If it rains, we’ll meet at the café.\nA: Is the return train still at six?\nB: The notice says it leaves at six.',
 transfer='Novo aviso: partida10h, chegada11h; atraso30min; partida10h30, chegada11h30; plataforma de partida muda1→4; volta17h. Parceiro espera11h10. Proponha encontro11h40 na entrada e alternativa café se chover. Escreva mensagem incluindo o que mudou e o que continua igual. Explique em português por que não se deve esperar na plataforma4 da chegada.',
 evidence='Nova chegada11h30; encontro proposto11h40 precisa de aceitação do parceiro. Plataforma4 é de partida, não prova local de chegada. Volta17h continua. Mensagem distingue “I suggest/Can we meet” de acordo já confirmado; aceitar blocos conhecidos.',
 review='No próximo encontro: chegada prevista12h, atraso de 15 min, encontro antigo12h10. Diga a chegada nova, proponha12h25 e crie condição para encontrar-se no café.',
 review_answer='Chegada12h15; proposta12h25; If it rains, we’ll meet at the café. O café não é afirmado como destino incondicional.',
 phon='Peça que o ouvinte registre fifteen e fifty em cartões distintos quando ditados por uma pessoa de apoio. Para horários, confirme com dígitos por escrito se necessário; velocidade não é requisito. A produção dos contrastes sem áudio fica pendente.',
 teacher='Não transformar atraso em horário final sem calcular a partir da hora original. Se o cálculo impedir, forneça atualização pronta e observe somente interpretação/produção. Pick up/get back aparecem como apoio lexical; não marcar padrões pronominais como cobertos aqui.')
]

UNITS += [
 dict(id='A2-03',title='Encontrar um objeto sem atribuí-lo à pessoa errada',prerequisites=['A2-02','A1-07','A1-08'],reading_questions=5,
 goal='Descrever um objeto perdido, reconstruir o momento do extravio e conferir propriedade antes da devolução.',
 targets=['Possessivos independentes','Indefinidos','Passado contínuo','Relativas definidoras simples'],
 support='coat = casaco; seat = assento; lost property = setor de achados e perdidos; collect = buscar item disponível; receipt = comprovante de compra/recebimento no contexto; missing = desaparecido/não encontrado; owner = proprietário; found = encontrou/encontrado; left = deixou; pocket = bolso; label = etiqueta; strip = faixa; silver = prateado; yours/mine/hers/ours/theirs = seu/meu/dela/nosso/deles sem nome depois; someone = alguém; anyone = alguém em pergunta/negação; nobody = ninguém; anything = algo em pergunta/negação. Os objetos e dados são fictícios.',
 explanation='My bag exige nome após my; mine substitui my bag: This bag is mine. Yours não tem apóstrofo. Someone is waiting usa singular; nobody já nega: Nobody called, não Nobody didn’t call neste padrão. Was/were + -ing mostra ação em curso: I was waiting when the bus arrived; arrived situa o evento. Who identifica pessoa e which/that identifica coisa nos exemplos: the person who found the bag; the bag that has a red label. Não repetir sujeito em who she found. Uma descrição compatível não prova propriedade por si só; a tarefa pede conferir todos os campos fornecidos.',
 readings=[('Relato ao balcão','I was waiting at the bus stop when a friend called me. I put my blue bag on the seat next to me. The bus arrived while I was talking. I picked up my coat and got on the bus, but I left the bag at the stop. There were two books and a silver bottle inside it. The bag has a red strip on the front and a label with the name LEE. I did not see anyone take it. Please let me know if someone brings it to lost property. I can describe the contents, but I don’t have a receipt for the bag.'),('Registro de achados e perdidos','Item A: blue bag, red strip, label LEE; two books and a silver bottle. Found on the seat at bus stop 4.\nItem B: blue bag, white strip, label LIA; one book and a black bottle. Found near the café.\nBoth bags are available for collection after three in the afternoon. A staff member will check the description before returning an item. This exercise uses fictional labels; do not send a real identity document or password. A matching colour alone is not enough to identify the owner.')],
 audio='Staff: Is the blue bag with the white strip yours?\nLee: No. Mine has a red strip.\nStaff: The one that has two books inside?\nLee: Yes, and a silver bottle.\nStaff: What were you doing when the bus arrived?\nLee: I was talking on the phone.\nStaff: The person who found your bag left it here. You can collect it after three.\nLee: Thank you. I’ll come at four.',
 questions=[('O relato permite concluir que alguém roubou a bolsa?','Não; a pessoa diz que a deixou e não viu alguém pegá-la.'),('O que estava acontecendo quando o ônibus chegou?','A pessoa falava ao telefone.'),('Qual registro corresponde a todos os dados fornecidos?','A; cor, faixa, etiqueta e conteúdo correspondem.'),('Por que B não é suficiente, embora também seja azul?','Faixa branca, etiqueta LIA e conteúdo diferente.'),('A partir de que hora os itens podem ser buscados?','Depois das 15h; não uma hora de retirada já combinada.'),('Qual detalhe Lee corrige na escuta?','Faixa branca → vermelha.'),('Quem encontrou a bolsa está identificado por nome?','Não; the person who found your bag descreve a pessoa sem nomeá-la.'),('Qual hora Lee propõe para ir?','16h; é posterior às 15h.')],
 practice=[('Complete: This is my bag. It is ___.','mine.'),('Corrija: Is this bag your’s?','Is this bag yours?'),('Complete: Someone ___ waiting. (is/are)','is.'),('Corrija no padrão-alvo: Nobody didn’t call.','Nobody called; se a intenção é ninguém ligou.'),('Complete: I ___ talking when the bus arrived.','was.'),('Complete: They ___ waiting when Jo called.','were.'),('Una: a person found the bag; the person is here. Use who.','The person who found the bag is here.'),('Corrija: The bag that it has a red label is mine.','The bag that has a red label is mine.'),('Relate ausência de resultado: I didn’t find ___. (anything/nothing)','anything, no padrão neutro ensinado.')],
 guided='A é Lee e vê só relato; B é atendente e vê registros A/B. B oferece primeiro B; A corrige cor da faixa e conteúdo. B confere todos os campos e combina visita após15h. Troquem papéis com uma bolsa inventada sem dados pessoais. Na rodada inventada, anotem previamente a descrição correta para conferir depois.',
 model='B: Is this one yours?\nA: No. Mine has a red strip. It’s the bag that has two books and a silver bottle.\nB: Were you waiting at the bus stop?\nA: Yes. I was talking when the bus arrived.',
 transfer='Novo relato: Kim estava lendo no café quando o telefone tocou; saiu sem a bolsa verde de etiqueta KIM, com um livro e duas canetas. Registro C: verde/KIM/um livro/duas canetas; D: verde/KIM/dois livros/sem canetas. Faça diálogo que rejeite D e identifique C, sem afirmar que houve roubo. Escreva mensagem curta em inglês e explique em português qual detalhe resolveu a ambiguidade.',
 evidence='C corresponde a todos os dados; etiqueta e cor sozinhas não separam C/D. I was reading when the phone rang (rang = tocou, apoio); Mine has one book and two pens. Não inventar identidade de quem levou a bolsa.',
 review='No encontro seguinte: Jo perdeu um guarda-chuva preto com etiqueta JO enquanto comprava pão. A: preto/JO; B: azul/JO. Use mine e uma relativa para identificar. Apoio: umbrella = guarda-chuva; buying = comprando.',
 review_answer='The umbrella that has a JO label and is black is mine / The black one is mine. I was buying bread. O relato não informa ladrão nem proprietário do item B.',
 phon='O ouvinte deve recuperar RED/WHITE e ONE/TWO em contrastes de descrição. Peça restituição do conteúdo, não apenas repetição da frase. Nome na etiqueta pode ser soletrado com apoio.',
 teacher='Não tratar rótulo de propriedade como prova real suficiente de identidade. Aqui o objetivo é conferir dados fictícios. Corrija my/mine usando presença/ausência de bag, sem exigir tradução palavra por palavra. A forma rang é fornecida na transferência e não deve virar pré-requisito oculto.'),
 dict(id='A2-04',title='Confirmar uma reserva e distinguir feito de pendente',prerequisites=['A2-01','A2-03','A1-07'],reading_questions=5,
 goal='Atualizar uma lista de preparação, distinguir experiência de acontecimento datado e pedir confirmação sem declarar concluído o que está pendente.',
 targets=['Perfect de experiência','Already, yet e just','Infinitivo de finalidade'],
 support='buy/bought = comprar/comprou ou comprado; book a room = reservar quarto/sala, verbo diferente de book livro; booking = reserva; attachment = anexo; reply to = responder a mensagem; confirm = confirmar; sent = enviado, particípio de send; received = recebido; paid = pago, particípio de pay; tried = experimentado; been = estado/ido como experiência; already = já; yet = ainda/já em perguntas/negações; just = acabou de; ever = alguma vez; never = nunca. A mensagem fictícia não pede cartão ou pagamento real.',
 explanation='Have/has + particípio relaciona experiência ou situação ao presente: Have you ever booked a room online? I’ve never tried it. Para evento datado fechado: I booked it yesterday, não I have booked it yesterday no padrão desta aula. Already marca conclusão: I’ve already sent the form. Yet verifica conclusão esperada: Have you received it yet? / I haven’t received it yet. Not yet não significa never. Just indica ação recente: I’ve just replied. To + verbo pode expressar finalidade: I called to confirm the time. Because explica uma razão com oração: I called because I needed help.',
 readings=[('Troca de mensagens com o centro','From Jo: I’ve already sent the booking form for Room B. I sent it yesterday at ten. I’ve attached the group list, but I haven’t received a confirmation yet. Have you received the attachment? I called this morning to check the total price, and a colleague said it was twenty-eight credits. I haven’t paid because I’m waiting for the confirmation. I’ve booked rooms before, but I’ve never used this centre. Please reply to this message to confirm the date, room and fee. I don’t need a new room; I need to know whether this request has been accepted.'),('Resposta e lista de verificação','From the centre: We have received your form and the attachment. We have not confirmed the room yet. Another staff member is checking the Saturday timetable. Please do not mark the booking as confirmed. We will reply when the check is complete.\nChecklist: form sent — yes; attachment received — yes; room confirmed — no; payment made — no.\nA sent request and a received attachment are different steps from an accepted booking. In this scenario, no payment is due before confirmation. This is a rule of this fictional transaction, not a universal rule for bookings.')],
 audio='Jo: Have you confirmed the room yet?\nStaff: Yes. We’ve just confirmed Room B for Saturday, from two to four.\nJo: Is the total fee twenty-eight credits?\nStaff: Yes. I’ve already sent the confirmation by email.\nJo: I haven’t received it yet. Could you check the address?\nStaff: Of course. Please use the fictional address on your form.\nJo: Thank you. I’ll check again.',
 questions=[('Quando Jo enviou o formulário?','Ontem às10h, evento datado.'),('Jo já usou este centro antes?','Não; nunca usou este centro, embora já tenha reservado salas em outros lugares.'),('Na resposta escrita, o anexo chegou?','Sim.'),('Na resposta escrita, a sala já está confirmada?','Não; ainda verificam o horário.'),('Por que Jo telefonou naquela manhã?','Para conferir o preço total; finalidade indicada por to check.'),('Que etapa muda para concluída na escuta?','Confirmação da sala B, sábado14h–16h.'),('O envio do e-mail prova que Jo já o recebeu?','Não; Jo diz que ainda não recebeu.'),('A conversa confirma que o pagamento foi feito?','Não; não há pagamento confirmado na fala.')],
 practice=[('Complete: I ___ already sent the form.','have.'),('Complete: She ___ just replied.','has.'),('Complete: Have you received it ___?','yet.'),('Negue conclusão esperada: I haven’t paid ___.','yet.'),('Escolha evento datado: I sent / have sent it yesterday.','I sent it yesterday.'),('Pergunte experiência com ever e book a room.','Have you ever booked a room?'),('Diferencie I’ve never booked e I haven’t booked yet.','Nunca teve essa experiência versus reserva esperada ainda não concluída.'),('Una com finalidade: I called. I wanted to confirm the time.','I called to confirm the time.'),('Complete razão: I called ___ I needed help.','because.')],
 guided='A tem checklist antes da chamada, B tem atualização: form received; room confirmed agora; confirmation sent; payment not received. A pergunta Have you…yet? e atualiza somente campos confirmados. B não deve responder “everything is done”. A confirma recebimento do e-mail apenas se receber cartão separado “email received”. Troquem papéis e omitam esse cartão na segunda rodada.',
 model='A: Have you confirmed the room yet?\nB: Yes. We’ve just confirmed it.\nA: Have you sent the email?\nB: Yes, we’ve already sent it.\nA: I haven’t received it yet. I called to check the details.',
 transfer='Novo serviço: pedido de bilhete enviado ontem; confirmação recebida hoje; pagamento ainda não realizado. Operador acabou de corrigir o nome e enviou nova confirmação, mas cliente ainda não recebeu a versão corrigida. Escreva atualização com already/just/yet, separando confirmação antiga e corrigida. Pergunte sobre experiência anterior com compra de bilhetes e peça uma data de uma compra usando passado simples. Use personagens e nenhum dado bancário real.',
 evidence='Pedido enviado ontem em past simple; confirmação original recebida; nome corrigido recentemente; nova confirmação enviada mas ainda não recebida; pagamento pendente. Exemplo: They’ve just corrected the name. They’ve already sent a new confirmation. I haven’t received it yet. Pergunta de experiência Have you ever bought a ticket online? (bought = comprado, apoio); data com When did you buy it?',
 review='No encontro seguinte: formulário enviado na segunda, recebido hoje; sala ainda não confirmada. Faça duas frases de situação atual, uma com data fechada e uma finalidade de telefonema.',
 review_answer='I sent the form on Monday. They’ve received it. They haven’t confirmed the room yet. I called to check the booking. Não converter recebido em aprovado.',
 phon='Nas atualizações, destacar o estado: ALREADY / NOT YET / JUST. Peça ao ouvinte para preencher feito ou pendente e justificar pelo trecho ouvido. Contrações podem ser expandidas sem perder sentido.',
 teacher='Há variedades que usam past simple com just/already em contextos semelhantes; aceitar formas naturais e registrar o alvo praticado sem declarar toda alternativa errada. Para esta sequência, contrastar data fechada com relevância atual. Esclareça received/confirmed se o obstáculo for léxico; não atribuir tudo ao perfect.'),
 dict(id='A2-05',title='Pedir ajuda, reorganizar um compromisso e entender regras',prerequisites=['A2-04','A1-06'],reading_questions=5,
 goal='Solicitar uma mudança de horário, pedir permissão e ajuda com agentes claros e distinguir obrigação, proibição e opção.',
 targets=['Conselho, obrigação e proibição','Permissão e pedido cortês','Infinitivo e -ing frequentes'],
 support='appointment = compromisso agendado; move an appointment = remarcar; tired = cansado, não diagnóstico; rest = descanso; break = pausa; allowed = permitido; optional = opcional; notebook = caderno; check in = registrar chegada; permission = permissão; must = obrigação no contexto; mustn’t = proibição; don’t have to = não precisa; should = conselho; enjoy = gostar de; decide = decidir; finish = terminar. Este é um centro de idiomas fictício, sem orientação clínica.',
 explanation='You have to check in obriga; you mustn’t take photos proíbe; you don’t have to bring a notebook dispensa. Don’t have to não significa mustn’t. Should oferece conselho no contexto: You should read the instructions first. Could I sit here? pede permissão para eu agir; Could you move my appointment? pede ação do outro. Want/need/decide + to-verbo: I need to change the time. Enjoy/finish + -ing: I enjoy learning; I finished reading. Esses padrões pertencem aos verbos; não há regra universal para trocar to por -ing.',
 readings=[('Instruções do centro de idiomas','Your speaking appointment is on Tuesday at ten. You have to check in at reception before the conversation. You mustn’t record other participants without permission. You don’t have to bring a notebook: it is optional. You can use the printed vocabulary card during the practice, but not during the separate observation task. If you need to change the time, contact reception before Monday at five. You should read these instructions before you arrive. You can ask for a short break between the two activities. This is a language practice appointment, not a health assessment.'),('Pedido de alteração','Hello. I need to move my Tuesday appointment because I work in the morning. I want to practise speaking, and I enjoy learning with a partner. Could you offer a time in the afternoon? I can come at two or three. I have finished reading the instructions. Could I use my own vocabulary card during the practice, or do I need to use the centre’s card? I sometimes feel tired after work, so I would also like to ask for a short break between the activities. I have not cancelled my appointment; I’m asking whether a change is possible.')],
 audio='Learner: Could you move my appointment to Tuesday at two?\nReceptionist: Two isn’t available. We can offer three.\nLearner: Three is fine. Could I use my own vocabulary card?\nReceptionist: Please use the centre’s card during the practice. You mustn’t use a card during the separate observation.\nLearner: Do I have to bring a notebook?\nReceptionist: No, you don’t have to. It’s optional.\nLearner: And a short break?\nReceptionist: Yes, between the activities.',
 questions=[('Qual é o compromisso original?','Terça às10h.'),('O que é obrigatório antes da conversa?','Registrar chegada na recepção.'),('Caderno é proibido?','Não; opcional. Don’t have to dispensa, não proíbe.'),('Qual é o limite para pedir mudança?','Antes de segunda às17h.'),('O pedido escrito já cancela o compromisso?','Não; solicita verificar possibilidade de mudança.'),('Qual novo horário é aceito na escuta?','Terça às 15h;14h não está disponível.'),('Qual cartão pode usar durante a prática?','O do centro; nenhum cartão na observação separada.'),('A pausa foi aceita em qualquer momento?','Foi aceita entre as atividades; não autorização indefinida.')],
 practice=[('Escolha proibição: mustn’t / don’t have to record.','mustn’t, quando a regra proíbe.'),('Escolha dispensa: You ___ bring a notebook.','don’t have to, no cenário opcional.'),('Dê conselho de ler instruções com should.','You should read the instructions.'),('Peça que recepcionista altere horário com Could.','Could you move my appointment?'),('Peça permissão para você sentar com Could.','Could I sit here?'),('Complete: I need ___ change the time.','to.'),('Corrija: I enjoy to learn with a partner.','I enjoy learning with a partner.'),('Complete: I’ve finished ___ the instructions. (read)','reading.'),('Quem age em Could you open the door?','O interlocutor; Could I open… pediria permissão para o falante agir.')],
 guided='A é estudante com agenda ocupada terça10h e livre14h/15h. B é recepção com apenas 15h livre. A pede alteração, pergunta regras de cartão e confirma pausa. B informa todos os limites sem transformar opcional em proibido. A escreve confirmação do novo horário e uma lista com três estados: obrigatório, proibido, opcional.',
 model='A: Could you move my appointment? I need to change the time.\nB: We can offer three on Tuesday.\nA: Thank you. Could I use a vocabulary card?\nB: During practice, use our card. You mustn’t use it during the observation.',
 transfer='Novo centro: compromisso quinta11h; estudante só pode16h; centro oferece16h30 e estudante aceita. Registro de chegada obrigatório; fotos proibidas em toda sala; caderno opcional; pausa após primeira atividade. Escreva pedido e confirmação separados, com limite para o que foi aceito. Faça uma pergunta de permissão e outra de ajuda e explique em português a diferença. Apoio: Thursday = quinta; four thirty in the afternoon =16h30.',
 evidence='Pedido16h não é confirmação; acordo final16h30 quinta. Obrigatório check in; proibido take photos; notebook optional; break depois da primeira atividade. Could I… e Could you… distinguem agentes. Não inventar permissão para usar cartões, ausente neste cenário.',
 review='No próximo encontro: água permitida; comida proibida; caderno dispensável; pedir que alguém repita instrução. Produza aviso curto com mustn’t/don’t have to e pedido com Could you.',
 review_answer='You mustn’t eat here. You don’t have to bring a notebook. Could you repeat that, please? Water is allowed. Sem regra de água obrigatória.',
 phon='Escute have to / don’t have to / mustn’t em três avisos e classifique obrigação, dispensa ou proibição. Confirme pelo sentido completo, não por uma palavra isolada; sem áudio, classificar como leitura.',
 teacher='Não usar tired/rest como diagnóstico ou aconselhamento de saúde. O cenário é negociação de condições numa atividade linguística. Se a negativa desaparecer na fala, peça reformulação e registre se o destinatário recebeu a regra correta.')
]

UNITS += [
 dict(id='A2-06',title='Explicar um processo e resolver uma dificuldade digital',prerequisites=['A2-04','A2-05','A1-05'],reading_questions=5,
 goal='Seguir um procedimento fictício, explicar etapas com foco no processo e pedir ajuda sem fornecer uma senha real.',
 targets=['Passiva básica em processos','Phrasal verbs e posição do objeto','Modo e comparação de advérbios'],
 support='screenshot = captura de tela; low = baixo; log in to = entrar em conta de um serviço; password = senha; attachment = anexo; reply to = responder a mensagem; turn off = desligar; turn on = ligar; look for = procurar; upload = enviar arquivo ao sistema; check = verificar; save = salvar; delete = apagar; recording = gravação; file name = nome do arquivo; clearly = claramente; carefully = cuidadosamente; slowly = devagar; well = bem; fast = rápido; hard = com esforço/intensamente; hardly = quase não. O sistema Luma é fictício; estas regras não descrevem o Lexio real.',
 explanation='Be + particípio apresenta processo: The recording is checked; The files are saved. O sujeito recebe a ação. Compare The room is clean (estado) e The room is cleaned every day (ação recorrente). Em turn off, o nome pode ir antes ou depois da partícula: turn the microphone off / turn off the microphone; com pronome, turn it off. Look for não segue essa separação: look for it, não look it for. Advérbios descrevem como: speak clearly, check carefully. Nem todos terminam em -ly: speak well, work hard, move fast. Hardly não é sinônimo de hard. Comparação de modo: more slowly than; better than, não more well.',
 readings=[('Guia de uma plataforma fictícia','In Luma, learners practise recording short messages. First, log in to the practice account provided on a classroom card. Do not use a real password in this exercise. Turn the microphone on, record a short greeting, and turn it off when you finish. Before you upload a file, check its name carefully. Each recording is saved in the practice folder. It is checked by the teacher before it is shared with the group. Files are not shared automatically. After the class, the teacher deletes the test recordings. This procedure belongs only to the fictional classroom system described here.'),('Mensagem de suporte e comparação de tentativas','Hello. I can log in, but I can’t find my recording. I’m looking for it in the practice folder. I checked the file name carefully. The attachment to this message is a screenshot of the folder, not a sound file. Please reply to this message with the next step. In my first recording, I spoke too fast and the listener missed my code. In the second recording, I spoke more slowly and said the code clearly. My partner understood it better. I worked hard on the second version, but I can hardly hear the first one because its volume is very low.')],
 audio='Support: Is the microphone on?\nLearner: Yes. Should I turn off it now?\nSupport: Turn it off after the recording. Then look for the file in the practice folder.\nLearner: I found it. Is it shared automatically?\nSupport: No. It is checked by the teacher first.\nLearner: I’ll check the name carefully before I upload it.\nSupport: Good. You don’t need to send us a password.',
 questions=[('Qual é a ordem das ações com o microfone?','Ligar, gravar, desligar após terminar.'),('Salvar significa compartilhar automaticamente com o grupo?','Não; professor verifica antes de compartilhar.'),('Quem apaga as gravações de teste segundo o guia fictício?','O professor, depois da aula.'),('O anexo da mensagem é áudio?','Não; screenshot da pasta, uma imagem da tela.'),('Por que hardly hear não significa ouvir com esforço intenso?','Hardly indica quase não ouvir; volume baixo. Work hard descreve esforço em outra frase.'),('Qual posição do pronome aparece na correção oral?','Turn it off; pronome entre verbo e partícula.'),('O estudante encontra o arquivo durante a conversa?','Sim: I found it.'),('Suporte pede senha?','Não; diz que não precisa enviá-la.')],
 practice=[('Complete: The recording ___ checked by the teacher.','is.'),('Complete: The files ___ saved in the practice folder.','are.'),('Passe para passiva: The teacher checks the recording.','The recording is checked by the teacher.'),('Diferencie The room is clean e is cleaned every day.','Estado limpo versus ação de limpar todos os dias.'),('Corrija: Turn off it.','Turn it off.'),('Corrija: Look it for.','Look for it.'),('Complete: She speaks English ___ (good/well).','well.'),('Complete: He checks the name ___ (careful/carefully).','carefully.'),('Compare duas falas: The second speaker speaks ___ slowly than the first.','more.'),('Reescreva com sentido: I can hardly hear it.','Quase não consigo ouvir; não “consigo ouvir com muito esforço” como equivalência de hard.')],
 guided='A recebe procedimento de Luma; B recebe problemas: microfone ainda ligado após gravação; procura arquivo na pasta errada; pensa que salvar já compartilhou. A dá três instruções com pronomes e explica a etapa passiva de verificação. B reformula cada etapa antes de “executar” em cartões de papel. Não acessar conta real.',
 model='A: Turn it off after you finish. Look for it in the practice folder.\nB: Is it shared when I save it?\nA: No. It is checked by the teacher first. Check the file name carefully.',
 transfer='Novo processo fictício: foto do cartaz é salva numa pasta de rascunhos; organizador confere; somente depois publica; microfone não é usado. Um colega diz que toda foto salva já está publicada. Corrija, explique três etapas com passiva e dê instrução para procurar o arquivo usando look for it. Compare leitura rápida demais com leitura clara do título. Apoios: photo, poster = foto, cartaz; draft folder = pasta de rascunhos; published = publicado; organiser = organizador.',
 evidence='The photo is saved in the draft folder. It is checked by the organiser. Then it is published. Look for it in the draft folder. Não adicionar gravação/microfone ao processo da foto. Comparação possível: Read the title more slowly; say it clearly.',
 review='No encontro seguinte: professor confere três arquivos antes de compartilhar. Escreva a etapa em passiva plural e dê instruções para desligar um aparelho e procurar um arquivo usando it. Diferencie hard/hardly.',
 review_answer='The files are checked by the teacher before they are shared. Turn it off. Look for it. Hard = com esforço; hardly = quase não. A passiva plural usa are.',
 phon='Use duas leituras de um código fictício, uma rápida e outra clara. O destinatário transcreve as duas; compare qual foi recuperável. A conclusão é sobre aquela amostra, não sobre superioridade geral de uma variedade.',
 teacher='Este cenário não é instrução para acessar ou modificar o produto real. Faça tudo com cartões. Não pedir senha nem gravação pessoal. Se passiva e posição de pronomes sobrecarregarem, separar dois encontros antes da tarefa integrada.'),
 dict(id='A2-07',title='Contar como uma rotina cultural mudou',prerequisites=['A2-03','A2-04','A2-06','A1-07'],reading_questions=5,
 goal='Comparar hábitos antigos e atuais, ordenar acontecimentos e preservar um contraste ao recontar uma história para outro público.',
 targets=['Hábito antigo com used to','Coordenação e subordinadas temporais'],
 support='used to = costumava/era habitualmente, com contraste explicado pelo contexto; rehearse = ensaiar; rehearsal = ensaio; choir = coro; stage = palco; audience = público; perform = apresentar-se; lend = emprestar para alguém; borrowed = pegou emprestado; neighbour = vizinho; before = antes; after = depois; while = enquanto; although = embora; moved = mudou-se; stopped = parou; still = ainda; since then = desde então, apoio receptivo. Relato e personagens são inteiramente fictícios.',
 explanation='Used to + base apresenta hábito ou estado passado: I used to rehearse every Friday. Para pergunta/negação no padrão escrito da aula: Did you use to sing? / I didn’t use to sing alone. Não confundir com be used to + -ing, que significa estar acostumado e não é o alvo aqui. Before/after ordenam; while situa simultaneidade; when liga um momento/evento. Although marca contraste: Although it rained, we performed. Não acrescentar but à mesma construção-alvo: Although it rained, but we performed. Used to sugere contraste, mas a descrição atual deve vir da fonte, não de adivinhação.',
 readings=[('Relato de Mara — uma mudança de rotina','I used to sing in a small choir on Friday evenings. We rehearsed in a neighbour’s living room because we didn’t have a rehearsal space. Before each rehearsal, I helped move the chairs. While the others prepared the music, I made tea. We usually performed at local events, and I never sang alone. Then I moved to another part of the city. I stopped going on Fridays because the journey was too long. Now I sing with a different group on Sunday mornings. I still enjoy singing with other people, but I sometimes practise alone at home. Moving changed my schedule, not my interest in music.'),('Programa e nota de uma apresentação','Last Sunday, Mara’s new group arrived at the community hall at nine. They checked the microphones before the audience came in. While two people checked the sound, the others arranged the chairs. Although it rained outside, the performance started at ten. The group sang three songs. After the performance, they talked to the audience and put the chairs away. Mara said: “I used to feel nervous before every performance. Today I felt calm because we had time to prepare.” Her comment describes this event; it does not prove that she will never feel nervous again.')],
 audio='Interviewer: Did you use to sing alone, Mara?\nMara: No, I didn’t. I used to sing with a choir on Fridays.\nInterviewer: Do you still sing on Fridays?\nMara: No. Now I sing with a group on Sundays.\nInterviewer: Did the rain stop the performance?\nMara: No. Although it rained, we performed indoors.\nInterviewer: What happened after the songs?\nMara: We talked to the audience and put the chairs away.',
 questions=[('Qual era o hábito antigo de Mara?','Cantar com coro às sextas à noite.'),('Por que parou de ir às sextas?','Mudou-se e o trajeto ficou longo demais.'),('Ela deixou de gostar de cantar com outras pessoas?','Não; mantém interesse e participa de outro grupo aos domingos.'),('O que ocorreu antes da entrada do público no domingo?','Conferiram os microfones; enquanto verificavam som, outros organizavam cadeiras.'),('Sentir-se calma nesse evento prova que nunca mais ficará nervosa?','Não; conclusão limitada àquela apresentação.'),('Na escuta, Mara confirma que cantava sozinha antes?','Não; cantava com coro.'),('A chuva impediu a apresentação?','Não; apresentaram-se em local fechado.'),('O que fizeram depois das músicas?','Conversaram com o público e guardaram as cadeiras.')],
 practice=[('Complete: I used to ___ on Fridays. (sing/singing)','sing.'),('Corrija pergunta: Did you used to sing alone?','Did you use to sing alone?'),('Negue hábito antigo: I used to perform alone.','I didn’t use to perform alone.'),('Una: conferiram microfones; depois público entrou. Use before.','They checked the microphones before the audience came in.'),('Una duas ações simultâneas: they checked the sound; we arranged chairs. Use while.','While they checked the sound, we arranged the chairs.'),('Corrija: Although it rained, but we performed.','Although it rained, we performed.'),('Complete: ___ the performance, we talked to the audience.','After, segundo a sequência do texto.'),('Uma pessoa diz I used to feel nervous, mas só relata calma hoje. Podemos afirmar nunca mais nervosa?','Não; é preciso limitar a inferência aos dados da fonte.')],
 guided='A entrevista Mara com cartões “antes” e “agora”; B representa Mara usando as duas fontes. A pergunta hábito, motivo da mudança e sequência do domingo. Depois A escreve nota de cinco frases para visitante que não conhece o grupo; B confere se não apareceu abandono da música ou hábito atual de sexta.',
 model='A: Did you use to sing on Fridays?\nB: Yes. Now I sing on Sundays.\nA: Why did the schedule change?\nB: I moved, and the journey was too long.\nA: Did you perform although it rained?\nB: Yes. We performed indoors.',
 transfer='Novo relato: Rui costumava desenhar sozinho às terças; agora desenha em grupo aos sábados porque trabalha na terça. Na última exposição, preparou etiquetas antes de o público entrar; enquanto Lia organizava mesas, Rui pendurava desenhos; embora estivesse frio, visitantes chegaram. Escreva relato com used to, now, before, while e although, depois recontagem em português para alguém que perdeu a exposição. Apoios: draw/drew = desenhar/desenhou; exhibition = exposição; hang/hung = pendurar/pendurou; drawings = desenhos; visitors = visitantes.',
 evidence='Rui used to draw alone on Tuesdays. Now he draws with a group on Saturdays because he works on Tuesdays. He prepared labels before the visitors came in. While Lia arranged the tables, Rui hung the drawings. Although it was cold, visitors came. Não inventar que o interesse em desenhar terminou.',
 review='No encontro posterior: Eva costumava ler em casa à noite; agora lê na biblioteca à tarde. Ontem devolveu livro antes de pegar outro; embora chovesse, foi à biblioteca. Relate hábito antigo/atual e dois eventos.',
 review_answer='Eva used to read at home in the evening. Now she reads at the library in the afternoon. She returned a book before she borrowed another. Although it rained, she went to the library. Returned/borrowed podem ser consultados como apoio, não verbos memorizados obrigatoriamente.',
 phon='Destaque OLD ROUTINE / NOW e palavras que ordenam eventos. O ouvinte organiza três cartões; se a ordem mudar, reformule a ligação temporal. Não avaliar apenas precisão de cada palavra isolada.',
 teacher='Não transformar used to em prova de mudança em todos os aspectos da vida. A fonte explica o que mudou e o que permaneceu. A tarefa cultural amplia contexto sem exigir conhecimento de repertório musical real. Put away é apoio no roteiro; sua análise de separabilidade não é alvo novo desta unidade.')
]
